import os, requests, urllib.parse, json
base='https://usegalaxy.org'; hid='bbd44e69cb8906b5960dcfad89f7680c'
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
h={'x-api-key':key}
tid='toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1'
r=requests.get(base+'/api/tools/'+urllib.parse.quote(tid,safe='')+'/build',headers=h,params={'history_id':hid},timeout=60)
data=r.json()
# recursively find select parameters and options containing hg/grch/human
terms=('hg38','GRCh38','Homo sapiens','human','hs1','hg19')
def walk(x,path=''):
    if isinstance(x,dict):
        if x.get('type')=='select' and 'options' in x:
            matches=[]
            for opt in x['options']:
                label=str(opt[0]); val=str(opt[1])
                if any(t.lower() in (label+' '+val).lower() for t in terms):
                    matches.append(opt)
            if matches:
                print('SELECT',path+'/'+x.get('name',''))
                for m in matches[:30]: print(' ',m)
        for k,v in x.items(): walk(v,path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+f'[{i}]')
walk(data.get('inputs'))
PY"

