/bin/bash -lc "python3 - <<'PY'
import os, requests, urllib.parse, json
base='https://usegalaxy.org'; hid='bbd44e69cb8906b5960dcfad89f7680c'
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
h={'x-api-key':key}
tid='toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1'
data=requests.get(base+'/api/tools/'+urllib.parse.quote(tid,safe='')+'/build',headers=h,params={'history_id':hid},timeout=60).json()

def summar(inp,indent=0):
    p='  '*indent
    if isinstance(inp,list):
        for x in inp: summar(x,indent)
        return
    if not isinstance(inp,dict): return
    print(f\"{p}{inp.get('model_class')} name={inp.get('name')} type={inp.get('type')} value={inp.get('value')} optional={inp.get('optional')}\")
    if inp.get('type')=='select':
        opts=inp.get('options',[])[:10]
        print(p+' options:', [(o[1], o[2] if len(o)>2 else None) for o in opts])
    if inp.get('model_class')=='Conditional':
        for c in inp.get('cases',[]):
            print(p+f\" CASE value={c.get('value')}\")
            summar(c.get('inputs'),indent+1)
    else:
        if 'inputs' in inp: summar(inp['inputs'],indent+1)

summar(data.get('inputs'))
PY"

